type BackgroundCta_SectionProps = Omit<
  BackgroundCta_CTAWithBackgroundImageProps,
  "theme"
>;

interface BackgroundCta_ContentProps {
  ctaHref: string;
  ctaLabel: string;
  emphasis: string;
  heading: string;
  headingColor: string;
  primaryButtonBackgroundColor: string;
  primaryButtonTextColor: string;
  secondaryButtonBorderColor: string;
  secondaryButtonTextColor: string;
  secondaryCtaHref: string;
  secondaryCtaLabel: string;
  spaceClassName: string;
  spaceHeight: number;
  subtext: string;
  textColor: string;
}

const BackgroundCta_CTAContent = ({
  ctaHref,
  ctaLabel,
  emphasis,
  heading,
  headingColor,
  primaryButtonBackgroundColor,
  primaryButtonTextColor,
  secondaryButtonBorderColor,
  secondaryButtonTextColor,
  secondaryCtaHref,
  secondaryCtaLabel,
  spaceClassName,
  spaceHeight,
  subtext,
  textColor,
}: BackgroundCta_ContentProps) => (
  <Section width="100%">
    <Fragment>
      <Row>
        <Column className="cta-background-side" style={{ width: "64px" }}>
          &zwj;
        </Column>
        <Column style={{ textAlign: "center" }}>
          <Section
            className={spaceClassName}
            style={{ lineHeight: `${spaceHeight}px` }}
          >
            &zwj;
          </Section>
          <Heading
            style={{
              color: headingColor,
              fontFamily: BackgroundCta_fontFamily,
              fontSize: "30px",
              fontWeight: 500,
              lineHeight: "36px",
              margin: 0,
              textAlign: "center",
            }}
            as="h2"
          >
            {heading}
          </Heading>
          <Section style={{ lineHeight: "24px" }}>&zwj;</Section>
          <Text
            style={{
              color: textColor,
              fontFamily: BackgroundCta_fontFamily,
              fontSize: "16px",
              fontWeight: 300,
              lineHeight: "24px",
              margin: 0,
              textAlign: "center",
            }}
          >
            {subtext}
            {emphasis ? (
              <>
                {" "}
                <span style={{ fontWeight: 700 }}>{emphasis}</span>
              </>
            ) : null}
          </Text>
          <Section style={{ lineHeight: "36px" }}>&zwj;</Section>
          <Section align="center" style={{ margin: "auto" }}>
            <Fragment>
              <Row>
                <Column className="cta-background-action-cell">
                  <Link
                    className="cta-background-primary"
                    href={ctaHref}
                    style={{
                      backgroundColor: primaryButtonBackgroundColor,
                      borderRadius: "8px",
                      color: primaryButtonTextColor,
                      display: "inline-block",
                      fontFamily: BackgroundCta_fontFamily,
                      fontSize: "16px",
                      fontWeight: 500,
                      lineHeight: "24px",
                      padding: "10px 22px",
                      textAlign: "center",
                      textDecoration: "none",
                    }}
                  >
                    {ctaLabel}
                  </Link>
                </Column>
                <Column
                  className="cta-background-action-cell cta-background-action-gap"
                  style={{ width: "24px" }}
                >
                  &zwj;
                </Column>
                <Column className="cta-background-action-cell">
                  <Link
                    href={secondaryCtaHref}
                    style={{
                      backgroundColor: "transparent",
                      border: `1px solid ${secondaryButtonBorderColor}`,
                      borderRadius: "8px",
                      color: secondaryButtonTextColor,
                      display: "inline-block",
                      fontFamily: BackgroundCta_fontFamily,
                      fontSize: "16px",
                      fontWeight: 600,
                      lineHeight: "24px",
                      padding: "9px 22px",
                      textAlign: "center",
                      textDecoration: "none",
