    backgroundColor: "#030712",
    cardBackgroundColor: "#030712",
    headingColor: "#fffffe",
    padded: false,
    textColor: "#d1d5db",
  },
  "flush-light": {
    backgroundColor: "#fffffe",
    cardBackgroundColor: "#fffffe",
    headingColor: "#030712",
    padded: false,
    textColor: "#4b5563",
  },
  "padded-dark": {
    backgroundColor: "#030712",
    cardBackgroundColor: "#030712",
